//! Acceptance tests: the multi-binary pass injects the scalar `core_ids` for
//! the core pass.
//!
//! The application's global core id comes from `rticx.toml`, not from
//! `#[app]`: the pass injects `core_ids = [core_id]` into the arguments, and
//! `rticx-core` consumes it natively. A single-core application with
//! `core_id = 1` must therefore compile without an unknown-argument warning,
//! and the runtime core checks generated by the software-task pass must
//! compare `current_core_id()` against the global id `1`.

use proc_macro2::TokenStream;
use quote::quote;
use rticx_core::RticMacroBuilder;
use rticx_core::mock_backend::MockCoreBackend;
use rticx_sw_pass::{SoftwarePass, SwPassBackend};
use rticx_xbin_pass::{AppTopology, XbinPass};

/// A software-task backend whose `current_core_id()` is a test expression, so
/// the generated `spawn` guards can be inspected.
struct TestSwBackend;

impl SwPassBackend for TestSwBackend {
    fn queue_path(&self) -> syn::Path {
        syn::parse_quote!(rticx::export::Queue)
    }

    fn generate_local_pend_fn(&self, _core: u32, mut empty_body_fn: syn::ItemFn) -> syn::ItemFn {
        empty_body_fn.block = Box::new(syn::parse_quote!({
            mock_local_pend(irq_nbr);
        }));
        empty_body_fn
    }

    fn generate_cross_pend_fn(
        &self,
        _core: u32,
        _empty_body_fn: syn::ItemFn,
    ) -> Option<syn::ItemFn> {
        None
    }

    fn current_core_id(&self) -> Option<syn::Expr> {
        Some(syn::parse_quote!(mock_current_core_id()))
    }
}

/// Macro arguments of the single-core application.
fn args() -> TokenStream {
    quote!(device = mypac, dispatchers = [IRQ0])
}

/// The project topology: the application's own global core id is `1`.
fn topology() -> AppTopology {
    AppTopology::new(1)
}

/// A single-core application with one core-local software task.
fn app() -> syn::ItemMod {
    syn::parse_quote! {
        mod app {
            #[init]
            fn init() -> TaskInits {
                TaskInits {}
            }

            #[sw_task(priority = 2)]
            struct Local;

            impl RticSwTask for Local {
                type SpawnInput = u32;
                fn exec(&mut self, _input: u32) {}
            }
        }
    }
}

#[test]
fn the_core_id_reaches_the_runtime_core_checks() {
    let mut builder = RticMacroBuilder::new(MockCoreBackend);
    builder.bind_pre_core_pass(XbinPass::disabled().with_topology(topology()));
    builder.bind_pre_core_pass(SoftwarePass::new(TestSwBackend));

    let code = builder.build_rtic_macro2(args(), app(), None).to_string();

    assert!(
        !code.contains("compile_error"),
        "the pipeline must accept the injected `core_ids` natively:\n{code}"
    );
    assert!(
        !code.contains("rticx_warn_unknown_app_core_ids"),
        "`core_ids` must not warn as an unknown argument:\n{code}"
    );

    // The single local core 0 maps to global 1, so the core-local spawn guard
    // compares against the global id.
    assert!(
        code.contains("if mock_current_core_id () != 1 { return Err (input) ; }"),
        "the core-local spawn guard must use the global id:\n{code}"
    );
    assert!(
        !code.contains("mock_current_core_id () != 0"),
        "a local core literal leaked into a runtime core check:\n{code}"
    );
}
